# helper for the weekly ops report
import csv
HOST = "db-12.corp.example"

def load_rows(path):
    with open(path) as f:
        return list(csv.DictReader(f))

def summarise(rows):
    return {"count": len(rows), "hosts": sorted({r["host"] for r in rows})}

